contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters that describe a minimal long call order where transfers are attempted.
    // Note: we cannot sign, so we rely on making order.maker be address(this) and providing
    // a signature that matches (for the checker this will be a symbolic bytes; SignatureChecker
    // may accept or reject—we observe revert flag). We keep arrays empty to avoid asset transfers.
    function run(
        address maker,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        bytes calldata signature
    ) public payable {
        require(address(this).balance >= 0);

        // Build an Order with isLong = true and isCall = true and no extra assets.
        C.Order memory order = C.Order({
            maker: maker,
            isCall: true,
            isLong: true,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        // Observables before the call
        bytes32 orderHash = c.hashOrder(order);
        uint256 makerBalanceBefore = 0;
        uint256 fulfillerBalanceBefore = 0;
        bool reverted = false;

        // Try to read balances via public ERC20 getter only if baseAsset is a contract address
        // We cannot assume ERC20 ABI here; but c exposes nothing for arbitrary token balances.
        // Instead we observe ownership of minted positions and Ether balance of contract.
        // Record whether order.maker and msg.sender already own tokens for these hashes.
        bool makerAlreadyOwns = false;
        bool fulfillerAlreadyOwns = false;

        // Safe view calls: ownerOf may revert if not minted; catch by try/catch style using low-level call.
        // Use staticcall to address(c).call to check ownerOf for maker and this contract.
        (bool okMaker, bytes memory dataMaker) = address(c).staticcall(abi.encodeWithSignature("ownerOf(uint256)", uint256(orderHash)));
        if (okMaker) {
            address owner = abi.decode(dataMaker, (address));
            makerAlreadyOwns = (owner == maker);
        }

        bytes32 opposite = c.hashOppositeOrder(order);
        uint256 oppositeId = uint256(opposite);
        (bool okFulf, bytes memory dataFulf) = address(c).staticcall(abi.encodeWithSignature("ownerOf(uint256)", oppositeId));
        if (okFulf) {
            address ownerF = abi.decode(dataFulf, (address));
            fulfillerAlreadyOwns = (ownerF == address(this));
        }

        // Attempt to fill the order, sending no ETH (long call requires msg.value == 0)
        try c.fillOrder{value: 0}(order, signature, new uint256[](0)) returns (uint256 positionId) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After state: check ownerOf for both position ids again (may revert if not minted)
        bool makerOwnsAfter = false;
        (bool okMaker2, bytes memory dataMaker2) = address(c).staticcall(abi.encodeWithSignature("ownerOf(uint256)", uint256(orderHash)));
        if (okMaker2) {
            address owner2 = abi.decode(dataMaker2, (address));
            makerOwnsAfter = (owner2 == maker);
        }

        bool fulfillerOwnsAfter = false;
        (bool okFulf2, bytes memory dataFulf2) = address(c).staticcall(abi.encodeWithSignature("ownerOf(uint256)", oppositeId));
        if (okFulf2) {
            address ownerF2 = abi.decode(dataFulf2, (address));
            fulfillerOwnsAfter = (ownerF2 == address(this));
        }

        // General rule (assert): If the call did NOT revert, then after fillOrder for a long call
        // the maker must own the token with id uint(orderHash) and the fulfiller (this contract)
        // must own the opposite position id. If either already owned them prior, that still must hold.
        // This captures that fillOrder mints both positions for successful long call fills.
        assert(reverted || (makerOwnsAfter && fulfillerOwnsAfter));
    }

    receive() external payable {}
}

