        });

        // Compute order hash and opposite order id via public view functions.
        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);
        uint256 orderId = uint256(orderHash);
        uint256 oppositeId = uint256(oppositeHash);

        // Try to call fillOrder; top-level state-changing call on c per constraints.
