        bool makerOwnsAfter = false;
        try c.ownerOf(orderId) returns (address ownerAfterMaker) {
            makerOwnsAfter = (ownerAfterMaker == maker);
        } catch {
            makerOwnsAfter = false;
        }

        bool fulfillerOwnsAfter = false;
        try c.ownerOf(oppositeId) returns (address ownerAfterFulfiller) {
            fulfillerOwnsAfter = (ownerAfterFulfiller == address(this));
        } catch {
            fulfillerOwnsAfter = false;
        }

        // General rule: if fillOrder did not revert, then maker must own orderId and this contract must own oppositeId.
        assert(reverted || (makerOwnsAfter && fulfillerOwnsAfter));
    }

    receive() external payable {}
