    constructor(C _c) { c = _c; }

    // We take parameters for a generic order and an ETH amount to forward when needed.
    function run(
        address maker,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        bytes calldata signature,
        uint256 ethAmount
    ) public payable {
        require(address(this).balance >= ethAmount);

        // Build an order that may cause two mints: the canonical case is any order where
        // fillOrder will mint both orderHash (maker) and oppositeOrder (fulfiller).
        // That occurs for all fills (the contract always calls _mint for maker and fulfiller in fillOrder).
        C.Order memory order = C.Order({
            maker: maker,
            isCall: true,
            isLong: true,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        // Read totalSupply before attempting fill
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        // Attempt to call fillOrder forwarding ethAmount
        try c.fillOrder{value: ethAmount}(order, signature, new uint256[](0)) returns (uint256 positionId) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read totalSupply after
        uint256 supplyAfter = c.totalSupply();

        // General rule: if fillOrder did not revert and the implementation path mints both positions,
        // then totalSupply increased by exactly 2. We assert: either it reverted, or supplyAfter == supplyBefore + 2.
        assert(reverted || supplyAfter == supplyBefore + 2);
    }

    receive() external payable {}
}

