contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We test that calling fillOrder either reverts or results in two minted positions:
    // - ownerOf(uint256(orderHash)) == order.maker
    // - ownerOf(positionId) == address(this) caller (the filler)
    // The function is payable to allow passing ETH as msg.value to c.fillOrder
    function run(C.Order memory order, bytes calldata signature, uint256[] memory floorAssetTokenIds, uint256 ethAmount) public payable {
        require(msg.value == ethAmount, "send ethAmount to test");
        // ensure we have the ETH available to forward if needed
        if (ethAmount > 0) require(address(this).balance >= ethAmount, "insufficient balance");

        // record contract balance before
        uint256 balanceBefore = address(c).balance;

        bool reverted;
        bytes32 orderHash = bytes32(0);
        uint256 positionId = 0;

        // attempt the call and capture if it reverts
        try c.fillOrder{value: ethAmount}(order, signature, floorAssetTokenIds) returns (uint256 pid) {
            reverted = false;
            positionId = pid;
            orderHash = c.hashOrder(order);
        } catch {
            reverted = true;
        }

        // Observables after call
        uint256 balanceAfter = address(c).balance;

        // If the call reverted, then nothing else is required by the property.
        // Otherwise, the maker must own the token with id == uint256(orderHash) and the filler (this contract)
        // must own the opposite-position token with id == positionId. Additionally, if ETH was forwarded
        // (ethAmount>0) then the contract balance should increase by exactly ethAmount when baseAsset==weth,
        // otherwise it should not increase due to ETH transfer in fillOrder.

        if (reverted) {
            // general rule: when reverted we assert that no new tokens were minted at those ids (ownerOf would revert)
            // but ownerOf reverts on not minted so we can't call it; instead assert balance didn't change
            assert(balanceAfter == balanceBefore);
        } else {
            // Non-reverted: check minted NFTs ownerships
            // ownerOf(uint256(orderHash)) == order.maker
            // ownerOf(positionId) == address(this)
            address makerOwner = c.ownerOf(uint256(orderHash));
            address fillerOwner = c.ownerOf(positionId);

            bool ownersOk = (makerOwner == order.maker) && (fillerOwner == address(this));

            // Check ETH balance behavior: if ethAmount>0 then baseAsset must equal weth for the call to accept ETH (contract enforces)
            // If baseAsset == weth, the contract will receive ETH via IWETH.deposit only in the call path where it uses msg.value
            // We assert balanceAfter >= balanceBefore and if ethAmount>0 then balanceAfter == balanceBefore + ethAmount when order.baseAsset==c.weth()

            bool wethMatches = (ethAmount > 0) ? (order.baseAsset == c.weth()) : true;

            bool balanceOk;
            if (ethAmount > 0 && order.baseAsset == c.weth()) {
                balanceOk = (balanceAfter == balanceBefore + ethAmount);
            } else {
                // no ETH should have been accepted into c for other cases
                balanceOk = (balanceAfter == balanceBefore);
            }

            assert(ownersOk && balanceOk);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Test: when the order.maker calls cancel(order) it must set cancelledOrders[orderHash] == true
    // and must not change address(c).balance (no ETH should be moved by cancel).
    // We take an ETH forwarding amount param but cancel is nonpayable; still require we hold that amount.
    function run(C.Order memory order, uint256 ethAmount) public payable {
        require(address(this).balance >= ethAmount, "insufficient balance for test");
        // Fund this contract as test caller if ethAmount > 0 by sending in msg.value when invoking run.

        // precondition: this contract must be the order.maker to be authorized to cancel
        // So we set order.maker to address(this)
        order.maker = address(this);

        // snapshot contract balance before
        uint256 balBefore = address(c).balance;

        // compute order hash before calling cancel
        bytes32 orderHash = c.hashOrder(order);

        bool reverted;
        // call cancel as maker (this contract). cancel is nonpayable, forward no ETH.
        try c.cancel(order) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable cancelled flag after
        bool cancelledFlag = c.cancelledOrders(orderHash);

        uint256 balAfter = address(c).balance;

        // General rule: if the caller was the maker (we set it so), cancel should NOT revert and must set cancelledOrders[orderHash]==true.
        // Additionally, cancel must not change the contract ETH balance.
        assert(reverted == false && cancelledFlag == true && balAfter == balBefore);
    }

    receive() external payable {}
}

